SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, CASE WHEN amount >= 1670 THEN 'PREMIUM' ELSE 'STANDARD' END AS amount_tier, COUNT(*) FILTER (WHERE status = 'REFUNDED') AS refunded_rows, MAX(amount) AS max_amount, ROUND(SUM(amount) / NULLIF(COUNT(CASE WHEN status = 'REFUNDED' THEN 1 END), 0), 2) AS amount_per_refunded, PERCENTILE_APPROX(amount, ARRAY(0.25, 0.5, 0.75)) AS amount_quartiles FROM payments GROUP BY DATE_TRUNC('WEEK', paid_at), CASE WHEN amount >= 1670 THEN 'PREMIUM' ELSE 'STANDARD' END HAVING amount_per_refunded < 1000000 ORDER BY max_amount DESC
